//! cswriter.ts — the small string-emitting C# writer (headers, usings,
//! file-scoped namespace, XML doc comments, indentation).

pub const CS_HEADER: &str =
    "// <auto-generated>\n//     Code generated by opensdk. DO NOT EDIT.\n// </auto-generated>";

pub const CSPROJ_HEADER: &str = "<!-- Code generated by opensdk. DO NOT EDIT. -->";

/// Assemble a complete C# file: header, SORTED using directives, file-scoped
/// namespace, and `\n\n`-separated declarations (empty dropped); trailing `\n`.
pub fn cs_file(usings: &[String], namespace_name: &str, decls: &[String]) -> String {
    let mut parts: Vec<String> = vec![CS_HEADER.to_string(), String::new()];
    if !usings.is_empty() {
        let mut sorted: Vec<String> = usings.to_vec();
        sorted.sort();
        parts.push(
            sorted
                .iter()
                .map(|u| format!("using {u};"))
                .collect::<Vec<_>>()
                .join("\n"),
        );
        parts.push(String::new());
    }
    parts.push(format!("namespace {namespace_name};"));
    parts.push(String::new());
    let body = decls
        .iter()
        .filter(|d| !d.is_empty())
        .cloned()
        .collect::<Vec<_>>()
        .join("\n\n");
    parts.push(body);
    format!("{}\n", parts.join("\n"))
}

/// Escape text for an XML doc comment.
pub fn escape_xml(text: &str) -> String {
    text.replace('&', "&amp;")
        .replace('<', "&lt;")
        .replace('>', "&gt;")
}

/// A C# `/// <summary>…</summary>` doc comment, or "" when empty.
pub fn cs_doc(text: Option<&str>) -> String {
    let raw = text.unwrap_or("").trim();
    if raw.is_empty() {
        return String::new();
    }
    let lines: Vec<&str> = raw
        .split('\n')
        .map(|l| l.trim())
        .filter(|l| !l.is_empty())
        .collect();
    if lines.len() == 1 {
        return format!("/// <summary>{}</summary>", escape_xml(lines[0]));
    }
    let mut out = vec!["/// <summary>".to_string()];
    for l in &lines {
        out.push(format!("/// {}", escape_xml(l)));
    }
    out.push("/// </summary>".to_string());
    out.join("\n")
}

/// Indent every non-empty line of a block by `depth` 4-space levels.
pub fn indent(block: &str) -> String {
    indent_by(block, 1)
}

pub fn indent_by(block: &str, depth: usize) -> String {
    let pad = "    ".repeat(depth);
    block
        .split('\n')
        .map(|line| {
            if line.is_empty() {
                line.to_string()
            } else {
                format!("{pad}{line}")
            }
        })
        .collect::<Vec<_>>()
        .join("\n")
}
